// 明示した 0・負・100 超は 400 `invalid_input`(engine のゼロ値「既定」をそのまま渡さない。ADR-0250 §3)。
type AdjustThresholdPercent = float64

// AllocMode 残り SP を回す側(bulk = H・B・D、offense = A または C と S)
type AllocMode string

// BulkCalcRequest defines model for BulkCalcRequest.
type BulkCalcRequest struct {
	// Attacker 計算に使う個体。SP と性格 ID から実数値を導出する
	Attacker Individual `json:"attacker"`

	// DefenderOverride 防御側の上書き(issue 272・274。ADR-0126・ADR-0214・ADR-0216)。省略した項目は上書きしない。
	// 指定した値は生成するすべての行(全プリセット × 全 itemVariants × 全特性)の防御側に一律で当てる。
	// プリセットが決める SP・性格・持ち物には触れない。省略・空オブジェクト・ゼロ値(ranks がすべて 0、
	// status が none)の応答は、defenderOverride を送らないときとバイト単位で同じ。
	// 逆算(ReverseRequest)には無い(既知の側は known.ranks / known.status で渡す。ADR-0216 §4)。
	//
	// - `ranks`: 防御側のランク補正。省略した能力は 0。プリセットの防御側はランク 0 なので、指定した値が
	//   そのまま全行に当たる。ダメージに効くのは技の分類が使う側だけ(物理は def、特殊は spd)で、
	//   急所のときは正のランクを無視する(1対1の計算と同じ規則)。各値が -6..+6 の外なら
	//   400 `invalid_input`(使わない側の能力でも拒否する)。応答の行(BulkDefender)にはランクを出さない
	//   (`stats` はランク補正前の実数値のまま)。
	// - `status`: 防御側の状態異常。未知の値は 400 `invalid_enum`(Individual.status と同じ)。
	//   **今のダメージ式は防御側の状態異常を見ない**(やけどの物理半減は攻撃側の状態だけ。ADR-0216 §3)ため、
	//   現時点では結果を変えない。防御側の状態で威力・防御が変わる技・特性に対応したときに効くようになる。
	DefenderOverride *DefenderOverride `json:"defenderOverride,omitempty"`

	// DefenderSpeciesKey {図鑑番号4桁}-{フォルム3桁}
	//
	// Example: 0445-000
	DefenderSpeciesKey SpeciesKey  `json:"defenderSpeciesKey"`
	Field              *FieldState `json:"field,omitempty"`
	Format             Format      `json:"format"`

	// ItemVariants 差し替えて比較する持ち物 ID(省略時は素の1通り)。null 要素は「持ち物なし」。
	// 65 件以上、または同じ値(null どうしを含む)の重複は 400 `invalid_input`(ADR-0208)。
	// 行の基本数は `len(presets) × len(itemVariants)`(上限 8 × 64 = 512)。特性ごとに結果が違う
	// ときだけ、その基本数のうち最大3倍(特性の候補数。ADR-0126・ADR-0214)まで行が分かれる。
	// 結果が同じ特性は1行にまとまるため、特性が効かない技では行数は変わらない。
	ItemVariants *[]*string   `json:"itemVariants,omitempty"`
	MoveId       string       `json:"moveId"`
	Options      *CalcOptions `json:"options,omitempty"`

	// Presets 使う防御側プリセットと行の順序。省略と空配列(`[]`)は同じで、技の分類に応じた既定セットになる。
	// 物理技は 5 件(none, hp, hb_boost, hb, hb_full)、
	// 特殊技は 5 件(none, hp, hd_boost, hd, hd_full)、
	// **変化技は 2 件(none, hp)のみ**。
	// 指定したときはその順に行を返す(分類に合わないプリセットも指定どおり返す)。
	// 同じ preset を2回以上含めると 400 `duplicate_preset`(`uniqueItems` 違反に対する
	// この操作の code。ADR-0208)。9 件以上は 400 `invalid_input`。
	// engine のカスタムプリセット定義(SP・性格を任意に決めたもの)は API に出さない。
	Presets *[]DefenderPreset `json:"presets,omitempty"`
}

// BulkCalcResult defines model for BulkCalcResult.
type BulkCalcResult struct {
	// DefenderSpeciesKey {図鑑番号4桁}-{フォルム3桁}
	//
	// Example: 0445-000
	DefenderSpeciesKey SpeciesKey    `json:"defenderSpeciesKey"`
	Rows               []BulkCalcRow `json:"rows"`
}

// BulkCalcRow defines model for BulkCalcRow.
type BulkCalcRow struct {
	// AbilityId この行の計算に使った防御側の特性(ADR-0126・ADR-0214)。種族は必ず1件以上の特性を持つため
	// 常に入る。
	AbilityId string `json:"abilityId"`

	// AbilityIds この行と結果が完全に同じになる特性の ID(abilityId が先頭。渡した/解決した順)。
	AbilityIds []string `json:"abilityIds"`

	// Defender 一括計算の1行で使った防御側の調整(SP・性格補正・実数値)
	Defender BulkDefender `json:"defender"`

	// ItemId この行の防御側の持ち物(持ち物なしは null)
	ItemId *string `json:"itemId,omitempty"`

	// Preset 防御側の代表調整(耐久が上がる順)。SP は能力ポイント(Lv50・個体値31固定)。
	// 性格の「無補正」は上昇・下降なし、「+B/-A」は防御上昇・攻撃下降のこと。
	// engine の PresetKey と同一文字列(docs/adr/0009-bulk-calc-presets.md §1)。
	// - `none`: 無振り(SP なし・無補正)。全分類
	// - `hp`: H振り(HP 32・無補正)。全分類
	// - `hb_boost`: H振り+B補正(HP 32・防御上昇 +B/-A)。物理
	// - `hb`: HB振り(HP 32・防御 32・無補正)。物理
	// - `hb_full`: HB特化(HP 32・防御 32・防御上昇 +B/-A)。物理
	// - `hd_boost`: H振り+D補正(HP 32・特防上昇 +D/-A)。特殊
	// - `hd`: HD振り(HP 32・特防 32・無補正)。特殊
	// - `hd_full`: HD特化(HP 32・特防 32・特防上昇 +D/-A)。特殊
	Preset DefenderPreset `json:"preset"`

	// PresetLabel 表示名(例 HB振り / HB特化 / H振り+B補正)
	PresetLabel string     `json:"presetLabel"`
	Result      CalcResult `json:"result"`
}

// BulkDefender 一括計算の1行で使った防御側の調整(SP・性格補正・実数値)
type BulkDefender struct {
	// Nature 性格補正の構造値。plus が +10%、minus が -10% を受ける能力。無補正は両方 null。
	// HP を指すことはない。
	Nature NatureModifier `json:"nature"`

	// NatureId nature と (plus, minus) が一致するマスタの性格 ID。無補正は、マスタの無補正性格を
	// ID の昇順で並べた最初のもの。該当する性格がマスタに無ければ null。
	NatureId *string `json:"natureId"`

	// Sp 能力ポイント
	Sp StatBlock `json:"sp"`

	// Stats 実数値(Lv50・個体値31)
	Stats StatBlock `json:"stats"`
}

// BulkFocus 耐久側の指数最大の基準(physical = H×B、special = H×D、both = min(H×B, H×D) → max)
type BulkFocus string

// CalcOptions defines model for CalcOptions.
type CalcOptions struct {
	// Critical 急所
	Critical *bool `json:"critical,omitempty"`
}

// CalcRequest defines model for CalcRequest.
type CalcRequest struct {
	// Attacker 計算に使う個体。SP と性格 ID から実数値を導出する
	Attacker Individual `json:"attacker"`

	// Defender 計算に使う個体。SP と性格 ID から実数値を導出する
	Defender Individual  `json:"defender"`
	Field    *FieldState `json:"field,omitempty"`
	Format   Format      `json:"format"`

	// MoveId 使用する技(attacker.moveId より優先)
	MoveId  string       `json:"moveId"`
	Options *CalcOptions `json:"options,omitempty"`
}

// CalcResult defines model for CalcResult.
type CalcResult struct {
	// Category 使った技の分類(WASM 境界の CalcResult と同じ。Web が型を共有するため)
	Category   MoveCategory `json:"category"`
	DefenderHP int          `json:"defenderHP"`

	// Effectiveness タイプ相性(0, 0.25, 0.5, 1, 2, 4)
	Effectiveness float64 `json:"effectiveness"`

	// Ko 確定数/乱数n発
	Ko        KOChance `json:"ko"`
	MaxDamage int      `json:"maxDamage"`

	// MaxPercent 最大ダメージの表示%(防御側 HP に対する割合)。小数第1位(0.1%刻み)で、
	// **四捨五入**する(ADR-0010 §3)。
	// 100 を超える場合は上限で切らず、そのまま返す(例 137.0)。
	// 逆算の入力の観測%(`Observation.percent` / `percentTenths`)とは別概念。
	MaxPercent float64 `json:"maxPercent"`
	MinDamage  int     `json:"minDamage"`

	// MinPercent 最小ダメージの表示%(防御側 HP に対する割合)。小数第1位(0.1%刻み)で、
	// **切り捨て**る(「最低これくらい入る」を保守的に示すため。ADR-0010 §3)。
	// 整数%に丸めてから小数にした値ではない。HP 比率から直接求める。
	// engine の 0.1% 単位の整数(tenths)を 10 で割っただけの値で、float で近似しない。
	MinPercent float64 `json:"minPercent"`

	// Rolls 16 段階の乱数ダメージ(非減少)
	Rolls []int `json:"rolls"`

	// Stab タイプ一致
	Stab bool `json:"stab"`

	// Unsupported この結果に付いた「未対応」の印(ADR-0123)。印なしは空配列(WASM 境界の CalcResult と同じ形)。
	Unsupported []UnsupportedMark `json:"unsupported"`
}

// DefenderOverride 防御側の上書き(issue 272・274。ADR-0126・ADR-0214・ADR-0216)。省略した項目は上書きしない。
// 指定した値は生成するすべての行(全プリセット × 全 itemVariants × 全特性)の防御側に一律で当てる。
// プリセットが決める SP・性格・持ち物には触れない。省略・空オブジェクト・ゼロ値(ranks がすべて 0、
// status が none)の応答は、defenderOverride を送らないときとバイト単位で同じ。
// 逆算(ReverseRequest)には無い(既知の側は known.ranks / known.status で渡す。ADR-0216 §4)。
//
//   - `ranks`: 防御側のランク補正。省略した能力は 0。プリセットの防御側はランク 0 なので、指定した値が
//     そのまま全行に当たる。ダメージに効くのは技の分類が使う側だけ(物理は def、特殊は spd)で、
//     急所のときは正のランクを無視する(1対1の計算と同じ規則)。各値が -6..+6 の外なら
//     400 `invalid_input`(使わない側の能力でも拒否する)。応答の行(BulkDefender)にはランクを出さない
//     (`stats` はランク補正前の実数値のまま)。
//   - `status`: 防御側の状態異常。未知の値は 400 `invalid_enum`(Individual.status と同じ)。
//     **今のダメージ式は防御側の状態異常を見ない**(やけどの物理半減は攻撃側の状態だけ。ADR-0216 §3)ため、
//     現時点では結果を変えない。防御側の状態で威力・防御が変わる技・特性に対応したときに効くようになる。
type DefenderOverride struct {
	// AbilityId 防御側の特性を1つに固定する。省略時は防御側の種族が持つ特性(最大3件。4件目がある種族は
	// Showdown の特殊枠 `"S"` を落とす。ADR-0105 §5 と同じ判断)をすべて候補として計算し、
	// 結果が完全に同じになる特性は1行にまとめ、違うときだけ行を分ける(ADR-0126)。
	// 指定した特性をその種族が持たない場合は 400 `invalid_input`、マスタに無い ID は
	// 400 `unknown_ability`。
	AbilityId *string `json:"abilityId,omitempty"`

	// Ranks ランク補正(-6..+6)。HP は持たない
	Ranks  *RankBlock       `json:"ranks,omitempty"`
	Status *StatusCondition `json:"status,omitempty"`
}

// DefenderPreset 防御側の代表調整(耐久が上がる順)。SP は能力ポイント(Lv50・個体値31固定)。
// 性格の「無補正」は上昇・下降なし、「+B/-A」は防御上昇・攻撃下降のこと。
// engine の PresetKey と同一文字列(docs/adr/0009-bulk-calc-presets.md §1)。
// - `none`: 無振り(SP なし・無補正)。全分類
// - `hp`: H振り(HP 32・無補正)。全分類
// - `hb_boost`: H振り+B補正(HP 32・防御上昇 +B/-A)。物理
// - `hb`: HB振り(HP 32・防御 32・無補正)。物理
// - `hb_full`: HB特化(HP 32・防御 32・防御上昇 +B/-A)。物理
// - `hd_boost`: H振り+D補正(HP 32・特防上昇 +D/-A)。特殊
// - `hd`: HD振り(HP 32・特防 32・無補正)。特殊
// - `hd_full`: HD特化(HP 32・特防 32・特防上昇 +D/-A)。特殊
type DefenderPreset string

// DeletionStatus `completed` = この端末のデータは残っていない。`partial` = 1回の上限に達したので残りがある
// (同じ要求を繰り返す。ADR-0209 §5.2)。
type DeletionStatus string

// Error エラーの本文。HTTP ステータスは `code` から決まる(ErrorCode の対応表)。
// `message` は日本語の説明で、Go の内部情報(スタック・型名)を含めない。
type Error struct {
	// Code 安定したエラーコード。WASM 境界(engine/wasmapi の Code* 定数。ADR-0011 §5・§13)と語彙を共通にし、
	// **同じ失敗は HTTP と WASM で同じ code** になる(ADR-0200)。
	//
	// WASM 境界と共通:
	// | code | 意味 | HTTP |
	// |---|---|---|
	// | invalid_json | JSON として壊れている / 型が合わない(整数のフィールドに小数を含む) | 400 |
	// | unknown_field | 契約にないフィールド | 400 |
	// | invalid_enum | 列挙(形式・タイプ・天候・フィールド・状態異常)の値が未知 | 400 |
	// | invalid_input | 入力検証(SP の範囲・合計、ランク、レベル、性格が HP など)。候補・観測の件数上限(`maxItems`)超過、持ち物候補の重複(`uniqueItems`)、`maxCandidates` の範囲外を含む(ADR-0208)。`getMovesByIds` の `ids` の件数超過・欠落も含む。調整(`/api/calc/adjust/*`)の発数・しきい値・補正・上限(ceiling)の範囲外、変化技での探索、下限が上限を超える配分(ADR-0250)も含む。team では構築名の長さ・メンバー数・技の重複・SP の範囲と合計・1端末が持てる構築の上限(ADR-0213 §2)も含む | 400 |
	// | unknown_preset | 未知の防御側プリセット | 400 |
	// | duplicate_preset | 防御側プリセットの重複 | 400 |
	// | invalid_preset | 防御側プリセットの定義が不正 | 400 |
	// | invalid_reverse_side | 逆算の side が defender / attacker のどちらでもない | 400 |
	// | no_observation | 観測が1件も無い | 400 |
	// | invalid_observation | 観測の指定が不正(percent / percentTenths / damage のちょうど1つでない・範囲外) | 400 |
	// | type_chart_missing | タイプ相性表が無い(HTTP では常にマスタ = 起動時に読み込んだ Store 側の不備で、クライアントの入力起因では起こらない) | 500 |
	// | invalid_type_chart | タイプ相性表の定義が不正(同上。HTTP では常にマスタ側の不備) | 500 |
	// | unknown_type | 相性表に無いタイプ | 400 |
	// | internal | 上記以外の失敗(回復した panic を含む) | 500 |
	//
	// HTTP だけのもの:
	// | code | 意味 | HTTP |
	// |---|---|---|
	// | missing_header | X-Device-Id / X-Session-Id が無い・空 | 400 |
	// | invalid_header | X-Device-Id / X-Session-Id が UUID でない・同名ヘッダの重複(UUID 形式の検証は gateway だけが行う。ADR-0202) | 400 |
	// | unknown_species | speciesKey がマスタに無い | 400 |
	// | unknown_move | moveId がマスタに無い | 400 |
	// | unknown_item | itemId がマスタに無い | 400 |
	// | unknown_ability | abilityId がマスタに無い | 400 |
	// | unknown_nature | natureId がマスタに無い | 400 |
	// | not_found | ルートが無い / このサービスの担当外の操作 / この端末が持っていないリソース ID(他端末のものか実在しないかを区別しない。403 にしない。ADR-0209 §6-2) | 404 |
	// | master_unavailable | マスタ(pokedex の MySQL)を参照できない | 503 |
	// | store_unavailable | 保存データの DB(record / team の TiDB)を参照できない。`master_unavailable` と分けるのは原因も復旧手順も別で、「計算はできるが保存はできない」状態(CLAUDE.md 絶対ルール5)をクライアントが区別できる必要があるため(ADR-0209 §5.3) | 503 |
	// | upstream_unavailable | gateway から下流のサービスに届かない(接続できない・タイムアウト・上流が未設定。ADR-0202) | 503 |
	Code    ErrorCode `json:"code"`
	Message string    `json:"message"`
}

